// AgentSessionError refuses execution or reports an unresolved mutation. Cause stays local.
type AgentSessionError struct {
	Code      string
	Retryable bool
	Message   string
	Cause     error
}

func (e *AgentSessionError) Error() string { return e.Code + ": " + e.Message }
func (e *AgentSessionError) Unwrap() error { return e.Cause }
func agentRefused(message string, cause error) error {
	return &AgentSessionError{Code: "agent_session_refused", Message: message, Cause: cause}
}
func agentInDoubt(cause error) error {
	return &AgentSessionError{Code: "agent_session_in_doubt", Message: "explicit reconciliation required; no call will be retried", Cause: cause}
}

